#!/bin/sh
# The one command that makes build.nbt from scratch: the parts, then the roof check, then into place.
set -eu
cd "$(dirname "$0")"
MCD="node /Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"
TMP="${TMPDIR:-/tmp}/villa-build.$$.nbt"          # .nbt: the toolkit picks the format by extension
trap 'rm -f "$TMP"' EXIT

node build.mjs "$TMP"

# the roof step (plan.md ROOFS): dry run first; skipped while the shell is still a stub (no walls to roof)
if grep -q '^// STUB' parts/shell.mjs; then
  echo "roof: skipped (shell is still a stub)"
else
  $MCD roof "$TMP" --dry-run --style shed
fi

mv "$TMP" build.nbt
$MCD info build.nbt
// villa-haiku: peristyle (plan.md PARTS 3, elements E08..E13). The garden court's colonnade, hedges, path legs, beds, fountain and statues.
// The court floor (grass) and the walkway mosaic come from the shell part; the bed and path-leg cells were left as air there for us.
import { FOUNTAIN, PATH, column, hedge, bed, fountain, statue } from "../vocab.mjs";

export function build(g) {
  // colonnade (E09): N row z29, S row z38, W column x11, E column x24
  for (const x of [11, 14, 21, 24]) { column(g, x, 29); column(g, x, 38); }
  for (const z of [32, 35]) { column(g, 11, z); column(g, 24, z); }

  // low hedges round the court (E11), gap at the axis x17..18
  hedge(g, [12, 30, 16, 30]);
  hedge(g, [19, 30, 23, 30]);
  hedge(g, [12, 37, 16, 37]);
  hedge(g, [19, 37, 23, 37]);
  hedge(g, [12, 31, 12, 36]);
  hedge(g, [23, 31, 23, 36]);

  // path legs across the walks into the court (smooth_stone at y1)
  g.fill([17, 1, 27], [18, 1, 29], PATH);
  g.fill([17, 1, 38], [18, 1, 40], PATH);

  // formal beds (E10): the statues stand in them, so they are set after the beds
  bed(g, [13, 31, 14, 36]);
  bed(g, [21, 31, 22, 36]);

  // fountain (E12): basin 6x6 in the court's centre, jet on the column top
  fountain(g, FOUNTAIN);

  // statues (E13): plinth, copper figure, cap; in the beds
  statue(g, 13, 33);
  statue(g, 22, 33);
  return g;
}
